import {registerTranslations} from './localization.js';
registerTranslations([["Film stills","影片静帧"],["A Martian news broadcast","一则来自火星的新闻"],["A clay-textured potato anchor turns the familiar television news format into a playful view of human space exploration.","具有黏土质感的土豆主播，将熟悉的电视新闻形式转化为观看人类太空探索的诙谐视角。"],["The potato anchor","土豆新闻主播"],["Humans through alien eyes","外星视角下的人类"],["A playful visual language","轻松诙谐的视觉语言"],["Reimagining the explorer","重新想象探索者"],["Aerospace ambition","航天抱负"],["An imagined civilization","想象中的文明"],["Making the film","短片制作过程"],["From character exploration to a finished broadcast","从角色探索到新闻节目成片"],["The production notes document a 23-hour workflow during a 24-hour AI filmmaking competition, combining image generation, a virtual presenter and broadcast post-production.","制作记录记载了在24小时 AI 创作比赛中完成的23小时工作流，将图像生成、虚拟主播与新闻节目后期制作相结合。"],["01 / Character & style","01 / 角色与风格"],["Midjourney supported early character exploration. Stable Diffusion, ComfyUI, LoRA and ControlNet were used to explore clay-like textures and control the image structure.","使用 Midjourney 探索初期角色形象，并结合 Stable Diffusion、ComfyUI、LoRA 与 ControlNet 探索黏土质感、控制画面结构。"],["02 / Image refinement","02 / 图像精修"],["Recraft was used for local corrections, scene adjustments and image expansion, bringing the generated characters and backgrounds into a more coherent visual world.","通过 Recraft 进行局部修正、场景调整和扩图，使生成角色与背景形成更连贯的视觉世界。"],["03 / Voice & performance","03 / 语音与表演"],["Dreamina was used for generated speech and lip synchronization, turning the designed presenter into a speaking character.","使用即梦生成语音并完成口型同步，让设计中的虚拟主播成为能够开口播报的角色。"],["04 / Broadcast & edit","04 / 节目包装与剪辑"],["After Effects and Premiere Pro brought together the presenter, footage, titles, ticker graphics and subtitles into the final news-format short film.","使用 After Effects 与 Premiere Pro，将主播、影像、标题、滚动新闻条和字幕整合为最终的新闻形式短片。"],["Production notes ↗","查看制作记录 ↗"]]);
const node=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text)n.textContent=text;return n;};
export function addPotatoStory(article,{openImage}){
 const section=node('section','case-generic potato-story');section.id='potato-stills';
 section.append(node('span','case-kicker','Film stills'),node('h2','','A Martian news broadcast'),node('p','','A clay-textured potato anchor turns the familiar television news format into a playful view of human space exploration.'));
 const grid=node('div','potato-stills');
 const images=[{src:'assets/potatoes/still-2.webp',name:"The potato anchor"},{src:'assets/potatoes/still-18.webp',name:"Humans through alien eyes"},{src:'assets/potatoes/still-72.webp',name:"A playful visual language"},{src:'assets/potatoes/still-90.webp',name:"Reimagining the explorer"},{src:'assets/potatoes/still-108.webp',name:"Aerospace ambition"},{src:'assets/potatoes/still-126.webp',name:"An imagined civilization"}];
 images.forEach((im,i)=>{const fig=node('figure');const b=node('button');b.type='button';b.setAttribute('aria-label',im.name);const img=node('img');img.src=im.src;img.alt=im.name;img.loading='lazy';img.decoding='async';b.append(img);b.onclick=()=>openImage(images,i,'What if Potatoes Ruled Mars');fig.append(b,node('figcaption','',im.name));grid.append(fig);});section.append(grid);article.append(section);
 const process=node('section','case-generic potato-story');process.id='potato-process';process.append(node('span','case-kicker','Making the film'),node('h2','','From character exploration to a finished broadcast'),node('p','',"The production notes document a 23-hour workflow during a 24-hour AI filmmaking competition, combining image generation, a virtual presenter and broadcast post-production."));
 const steps=node('div','potato-steps');
 {const step=node('div');step.append(node('h3','',"01 / Character & style"),node('p','',"Midjourney supported early character exploration. Stable Diffusion, ComfyUI, LoRA and ControlNet were used to explore clay-like textures and control the image structure."));steps.append(step);}
{const step=node('div');step.append(node('h3','',"02 / Image refinement"),node('p','',"Recraft was used for local corrections, scene adjustments and image expansion, bringing the generated characters and backgrounds into a more coherent visual world."));steps.append(step);}
{const step=node('div');step.append(node('h3','',"03 / Voice & performance"),node('p','',"Dreamina was used for generated speech and lip synchronization, turning the designed presenter into a speaking character."));steps.append(step);}
{const step=node('div');step.append(node('h3','',"04 / Broadcast & edit"),node('p','',"After Effects and Premiere Pro brought together the presenter, footage, titles, ticker graphics and subtitles into the final news-format short film."));steps.append(step);}
 process.append(steps);
 const processImages=[{src:'assets/potatoes/process-1.webp',name:'01 / Character & style'},{src:'assets/potatoes/process-2.webp',name:'02 / Image refinement'},{src:'assets/potatoes/process-3.webp',name:'03 / Voice & performance'}];
 const gallery=node('div','potato-stills');processImages.forEach((im,i)=>{const fig=node('figure'),b=node('button'),img=node('img');b.type='button';b.setAttribute('aria-label',im.name);img.src=im.src;img.alt=im.name;img.loading='lazy';img.decoding='async';b.append(img);b.onclick=()=>openImage(processImages,i,'Making the film');fig.append(b,node('figcaption','',im.name));gallery.append(fig);});process.append(gallery);
 const link=node('a','case-document','Production notes ↗');link.href='https://www.notion.so/1d426400bd4180a4a768e8effda914cc';link.target='_blank';link.rel='noopener';process.append(link);article.append(process);
}

